import os
import requests

DEVICES = ["sw1.example.net", "sw2.example.net"]
HEADERS = {"Accept": "application/yang-data+json"}
AUTH = (os.environ["MON_USER"], os.environ["MON_PASS"])
PATH = "/restconf/data/ietf-interfaces:interfaces-state/interface"

for host in DEVICES:
    r = requests.get(f"https://{host}{PATH}", headers=HEADERS, auth=AUTH,
                     verify="/etc/pki/internal-ca.pem", timeout=10)
    r.raise_for_status()
    for i in r.json()["ietf-interfaces:interface"]:
        if i["oper-status"] != "up" and i["name"].startswith("GigabitEthernet"):
            print(f"{host} {i['name']} oper-status={i['oper-status']}")

